// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    RecordingToken token;

    function setUp() public {
        c = new C();
        token = new RecordingToken();
    }

    function testFuzz_property(address actor, uint256 v, address to) public {
        vm.assume(actor != address(0) && to != address(0));
        vm.assume(v < type(uint256).max);
        address[] memory tos = new address[](1);
        tos[0] = to;
        vm.prank(actor);
        c.transfer(actor, address(token), tos, v);
        assertTrue(token.lastAmount() == v && token.lastFrom() == actor && token.lastTo() == to);
    }
}

contract RecordingToken {
    uint256 public lastAmount;
    address public lastFrom;
    address public lastTo;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}
